751: static int idma_drain(struct idma_stream *s)
752: {
753: 	u64 done;
754: 	int ret;
755: 
756: 	if (!s->in_flight)
757: 		return s->retain ? -EIO : 0;
758: 	ret = readq_poll_timeout(s->idma->reg + IDMA_DONE_REG_OFFSET, done,
759: 				 done == s->transfer_id, 0, IDMA_XFER_TIMEOUT_US);
760: 	if (ret) {
761: 		idma_quarantine(s);
762: 		return ret;
763: 	}
764: 	s->in_flight = false;
765: 	if (s->diagnostic && !s->batch_started)
766: 		s->diagnostic->warm_drained++;
767: 	if (!s->batch_configured)
768: 		s->touched_end = max(s->touched_end, s->offset + s->chunk);
769: 	return 0;

772: static int idma_verify(struct idma_stream *s)
773: {
774: 	size_t i;
775: 
776: 	if (s->retain)
777: 		return -EIO;
778: 	/* Verify untouched bytes as well, and source integrity independently. */
779: 	for (i = 0; i < s->size; i++) {
780: 		u64 pattern = idma_pattern(s, i / sizeof(u64));
781: 		u8 value = ((u8 *)&pattern)[i % sizeof(u64)];
782: 		u8 expected = (i < s->touched_end ||
783: 			       i >= s->size - s->touched_tail) ? value : (u8)~value;
784: 		u8 src = READ_ONCE(((u8 *)s->src)[i]);
785: 		u8 dst = READ_ONCE(((u8 *)s->dst)[i]);
786: 
787: 		if (src != value || dst != expected) {
788: 			phys_addr_t src_pa, dst_pa, src_pte_pa, dst_pte_pa;
789: 			u8 src_after, dst_after;
790: 
791: 			/*
792: 			 * On this CVA6, FENCE.I also invalidates the WT data cache.
793: 			 * Probe only after failure and safe drain; preserve the failure.
794: 			 * This is not a generic DMA cache-coherency fix.
795: 			 */
796: 			local_flush_icache_all();
797: 			src_after = READ_ONCE(((u8 *)s->src)[i]);
798: 			dst_after = READ_ONCE(((u8 *)s->dst)[i]);
799: 
800: 			src_pa = page_to_phys(idma_buffer_page(s->src + i)) +
801: 				 offset_in_page(s->src + i);
802: 			dst_pa = page_to_phys(idma_buffer_page(s->dst + i)) +
803: 				 offset_in_page(s->dst + i);
804: 			src_pte_pa = iommu_iova_to_phys(s->domain, s->src_iova + i);
805: 			dst_pte_pa = iommu_iova_to_phys(s->domain, s->dst_iova + i);
806: 
807: 			s->stats->data_errors++;
808: 			dev_err(s->dev,
809: 				"experiment data mismatch: id=%d did=%u offset=%zu touched_end=%zu size=%zu chunk=%u src=%02x src_after_fence_i=%02x expected_src=%02x dst=%02x dst_after_fence_i=%02x expected_dst=%02x src_iova=%#lx dst_iova=%#lx src_pa=%pa dst_pa=%pa src_pte_pa=%pa dst_pte_pa=%pa\n",
810: 				s->idma->id, s->idma->did, i, s->touched_end,
811: 				s->size, s->chunk, src, src_after, value,
812: 				dst, dst_after, expected,
813: 				s->src_iova + i, s->dst_iova + i, &src_pa,
814: 				&dst_pa, &src_pte_pa, &dst_pte_pa);
815: 			return -EILSEQ;
816: 		}
817: 	}
818: 	return 0;

821: /* Batch mode still uses DEFAULT read/write copies. STOP never cancels AXI. */
822: static int idma_batch_configure(struct idma_stream *s, u64 count)
823: {
824: 	void __iomem *base = s->idma->reg;
825: 
826: 	if (readq(base + IDMA_BATCH_MAGIC_OFFSET) != IDMA_BATCH_MAGIC)
827: 		return -EOPNOTSUPP;
828: 	if (readq(base + IDMA_BATCH_CONTROL_OFFSET) & 2)
829: 		return -EBUSY;
830: 	writeq(0, base + IDMA_BATCH_CONTROL_OFFSET);
831: 	writeq(count, base + IDMA_BATCH_TARGET_OFFSET);
832: 	writeq(s->size / PAGE_SIZE, base + IDMA_BATCH_PAGES_OFFSET);
833: 	writeq(1, base + IDMA_BATCH_CONTROL_OFFSET);
834: 	s->batch_configured = true;
835: 	s->next_offset = 0;
836: 	return readq(base + IDMA_BATCH_CONTROL_OFFSET) == 1 ? 0 : -EIO;
837: }
838: 
839: static void idma_batch_stop(struct idma_stream *s)
840: {
841: 	if (s && s->batch_configured && s->batch_started)
842: 		writeq(2, s->idma->reg + IDMA_BATCH_CONTROL_OFFSET);
843: }
844: 
845: static int idma_batch_collect(struct idma_stream *s)
846: {
847: 	u64 status, issued, completed;
848: 
849: 	if (!s || !s->batch_configured)
850: 		return 0;
851: 	if (s->retain)
852: 		return -EIO;
853: 	status = readq(s->idma->reg + IDMA_BATCH_CONTROL_OFFSET);
854: 	if (status & 2) {
855: 		idma_quarantine(s);
856: 		return -EIO;
857: 	}
858: 	if (s->batch_started) {
859: 		issued = readq(s->idma->reg + IDMA_BATCH_ISSUED_OFFSET);
860: 		completed = readq(s->idma->reg + IDMA_BATCH_COMPLETED_OFFSET);
861: 		s->stats->submitted = issued;
862: 		s->stats->completed = completed;
863: 		s->stats->completed_bytes = completed * PAGE_SIZE;
864: 		if (s->reverse)
865: 			s->touched_tail = max(s->touched_tail,
866: 				      (size_t)min(completed, (u64)(s->size / PAGE_SIZE)) * PAGE_SIZE);
867: 		else
868: 			s->touched_end = max(s->touched_end,
869: 				     (size_t)min(completed, (u64)(s->size / PAGE_SIZE)) * PAGE_SIZE);
870: 		if (issued != completed || issued > IDMA_EXPERIMENT_MAX_TRANSFERS)
871: 			return -EIO;
872: 	}
873: 	return status >> 32 ? -EIO : 0;

937: static int idma_validate(const struct idma_experiment *e)
938: {
939: 	if (PAGE_SIZE != SZ_4K)
940: 		return -EOPNOTSUPP;
941: 	if (e->abi_version != IDMA_EXPERIMENT_ABI || e->struct_size != sizeof(*e))
942: 		return -EPROTO;
943: 	if (e->flags || memchr_inv(e->reserved, 0, sizeof(e->reserved)))
944: 		return -EINVAL;
945: 	if (!e->victim_pages || e->victim_pages > IDMA_MAX_PAGES ||
946: 	    !e->aggressor_pages || e->aggressor_pages > IDMA_MAX_PAGES ||
947: 	    !e->chunk_bytes || e->chunk_bytes > PAGE_SIZE ||
948: 	    PAGE_SIZE % e->chunk_bytes || !e->victim_transfers ||
949: 	    e->victim_transfers > IDMA_EXPERIMENT_MAX_TRANSFERS ||
950: 	    e->warmup_transfers > IDMA_EXPERIMENT_MAX_TRANSFERS ||
951: 	    !e->run_timeout_ms || e->run_timeout_ms > IDMA_MAX_RUN_TIMEOUT_MS)
952: 		return -EINVAL;
953: 	return 0;
954: }

2390: 	ret = mutex_lock_interruptible(&idma_experiment_lock);
2391: 	if (ret)
2392: 		goto out_copy;
2393: 	if (idma_any_quarantined()) {
2394: 		ret = -EIO;
2395: 		goto out_unlock;
2396: 	}
2397: 	if (cfg) {
2398: 		ret = idma_research2_preflight(victim, cfg);
2399: 		if (ret)
2400: 			goto out_unlock;
2401: 	}
2402: 	if (e.aggressor_id != IDMA_EXPERIMENT_NO_AGGRESSOR) {
2403: 		aggressor = idma_get_instance(e.aggressor_id);
2404: 		if (!aggressor) {
2405: 			ret = -ENODEV;
2406: 			goto out_unlock;
2407: 		}
2408: 		if (aggressor == victim || aggressor->did == victim->did) {
2409: 			ret = -EINVAL;
2410: 			goto out_put;
2411: 		}
2412: 		e.aggressor_did = aggressor->did;
2413: 		a = &streams[1];
2414: 	}

2448: 	ret = idma_stream_prepare(v, victim, e.victim_pages, e.chunk_bytes, &e.victim);
2449: 	if (ret)
2450: 		goto out_cleanup;
2451: 	v->composition_trace = comp_trace;
2452: 	if (a) {
