480: static bool riscv_iommu_post_sync(struct riscv_iommu_device *iommu,
481: 				  struct riscv_iommu_command *cmd, bool sync)
482: {
483: 	u32 head, tail, next, last;
484: 	unsigned long flags;
485: 
486: 	spin_lock_irqsave(&iommu->cq_lock, flags);
487: 	head = riscv_iommu_readl(iommu, RISCV_IOMMU_REG_CQH) & (iommu->cmdq.cnt - 1);
488: 	tail = riscv_iommu_readl(iommu, RISCV_IOMMU_REG_CQT) & (iommu->cmdq.cnt - 1);
489: 	last = iommu->cmdq.lui;
490: 	if (tail != last) {
491: 		spin_unlock_irqrestore(&iommu->cq_lock, flags);
492: 		/* TRY AGAIN */
493: 		dev_err(iommu->dev, "IOMMU CQT: %x != %x (1st)\n", last, tail);
494: 		spin_lock_irqsave(&iommu->cq_lock, flags);
495: 		tail =
496: 		    riscv_iommu_readl(iommu, RISCV_IOMMU_REG_CQT) & (iommu->cmdq.cnt - 1);
497: 		last = iommu->cmdq.lui;
498: 		if (tail != last) {
499: 			spin_unlock_irqrestore(&iommu->cq_lock, flags);
500: 			dev_err(iommu->dev, "IOMMU CQT: %x != %x (2nd)\n", last, tail);
501: 			spin_lock_irqsave(&iommu->cq_lock, flags);
502: 		}
503: 	}
504: 
505: 	next = (last + 1) & (iommu->cmdq.cnt - 1);
506: 	if (next != head) {
507: 		struct riscv_iommu_command *ptr = iommu->cmdq.base;
508: 		ptr[last] = *cmd;
509: 		wmb();
510: 		riscv_iommu_writel(iommu, RISCV_IOMMU_REG_CQT, next);
511: 		iommu->cmdq.lui = next;
512: 	}
513: 
514: 	spin_unlock_irqrestore(&iommu->cq_lock, flags);
515: 
516: 	if (sync && head != next) {
517: 		cycles_t start_time = get_cycles();
518: 		while (1) {
519: 			last = riscv_iommu_readl(iommu, RISCV_IOMMU_REG_CQH) &
520: 			    (iommu->cmdq.cnt - 1);
521: 			if (head < next && last >= next)
522: 				break;
523: 			if (head > next && last < head && last >= next)
524: 				break;
525: 			if (RISCV_IOMMU_TIMEOUT < (get_cycles() - start_time)) {
526: 				dev_err(iommu->dev, "IOFENCE TIMEOUT\n");
527: 				return false;
528: 			}
529: 			cpu_relax();
530: 		}
531: 	}
532: 
533: 	return next != head;
534: }
