1562: 	/* allocate root pages, initialize io-pgtable ops, etc. */
1563: 	ret = riscv_iommu_domain_finalize(domain, ep->iommu);
1564: 	if (ret < 0) {
1565: 		dev_err(dev, "can not finalize domain: %d\n", ret);
1566: 		mutex_unlock(&ep->lock);
1567: 		mutex_unlock(&domain->lock);
1568: 		return ret;
1569: 	}
1570: 
1571: 	dev_info(dev, "domain id %u %s type %d attach\n", domain->id,
1572: 		 domain->g_stage ? "G-Stage" : "S-Stage", domain->domain.type);
1573: 
1574: 	/*
1575: 	 * Update device context:
1576: 	 *  G-Stage : only if domain->g_stage
1577: 	 *  S-Stage : only if domain->s_stage. rely on OS not to update S-Stage while G-Stage valid.
1578: 	 */
1579: 	if (domain->g_stage) {
1580: 		/*
