1582: 		 * for S-Stage. VMM is responsible for more restrictive
1583: 		 * guest VA translation scheme configuration.
1584: 		 */
1585: 		dc->iohgatp = cpu_to_le64(riscv_iommu_domain_atp(domain));
1586: 		dc->fsc = 0ULL; /* RISCV_IOMMU_DC_FSC_MODE_BARE */ ;
1587: 	} else {
1588: 		/*
1589: 		 * S-Stage translation table does not ammend G-Stage.
1590: 		 */
1591: 		val = FIELD_PREP(RISCV_IOMMU_DC_TA_PSCID, domain->id);
1592: 		dc->ta = cpu_to_le64(val);
1593: 		dc->fsc = cpu_to_le64(riscv_iommu_domain_atp(domain));
1594: 	}
1595: 	wmb();
1596: 	/*
1597: 	 * Mark device context as valid, synchronise device context cache.
1598: 	 */
1599: 	val = RISCV_IOMMU_DC_TC_V;
1600: 	if (ep->pasid_enabled)
1601: 		val |= RISCV_IOMMU_DC_TC_EN_ATS | RISCV_IOMMU_DC_TC_EN_PRI;
1602: 
1603: 	/* Enable QEMU custom extension for auto-pri generation */
1604: 	if (ep->pasid_enabled)
1605: 		val |= 1ULL << 32;
1606: 
1607: 	if (ep->iommu->cap & RISCV_IOMMU_CAP_AMO)
1608: 		val |= RISCV_IOMMU_DC_TC_GADE | RISCV_IOMMU_DC_TC_SADE;
1609: 	dc->tc = cpu_to_le64(val);
1610: 	wmb();
1611: 	ep->domain = domain;
1612: 
1613: 	list_add_tail(&ep->domains, &domain->endpoints);
1614: 	mutex_unlock(&ep->lock);
1615: 	mutex_unlock(&domain->lock);
1616: 	riscv_iommu_iodir_inv_devid(ep->iommu, ep->devid);
1617: 
1618: 	return 0;

1730: static void riscv_iommu_flush_iotlb_range(struct iommu_domain *iommu_domain,
1731: 					  unsigned long *start, unsigned long *end,
1732: 					  size_t *pgsize)
1733: {
1734: 	struct riscv_iommu_domain *domain = iommu_domain_to_riscv(iommu_domain);
1735: 	struct riscv_iommu_command cmd;
1736: 	struct riscv_iommu_endpoint *endpoint;
1737: 	// unsigned long iova;
1738: 	unsigned long payload;
1739: 
1740: 	if (domain->mode == RISCV_IOMMU_DC_FSC_MODE_BARE)
1741: 		return;
1742: 
1743: 	/* Domain not attached to an IOMMU! */
1744: 	BUG_ON(!domain->iommu);
1745: 
1746: 	if (start && end) {
1747: 		payload = riscv_iommu_ats_inval_payload(*start, *end, true);
1748: 	} else {
1749: 		payload = riscv_iommu_ats_inval_all_payload(true);
1750: 	}
1751: 
1752: 	if (domain->g_stage) {
1753: 		riscv_iommu_cmd_inval_gvma(&cmd);
1754: 		riscv_iommu_cmd_inval_set_gscid(&cmd, domain->id);
1755: 	} else {
1756: 		riscv_iommu_cmd_inval_vma(&cmd);
1757: 		// riscv_iommu_cmd_inval_set_pscid(&cmd, domain->id);
1758: 	}
1759: 
1760: 	// if (start && end && pgsize) {
1761: 	// 	/* Cover only the range that is needed */
1762: 	// 	for (iova = *start; iova <= *end; iova += *pgsize) {
1763: 	// 		printk("Sending IOTINVAL with ADDR");
1764: 	// 		riscv_iommu_cmd_inval_set_addr(&cmd, iova);
1765: 	// 		riscv_iommu_post(domain->iommu, &cmd);
1766: 	// 	}
1767: 	// } else {
1768: 		riscv_iommu_post(domain->iommu, &cmd);
1769: 	// }
1770: 	riscv_iommu_iofence_sync(domain->iommu);
1771: 
1772: 	/* ATS invalidation for every device and for every translation */
1773: 	list_for_each_entry(endpoint, &domain->endpoints, domains) {
1774: 		if (!endpoint->pasid_enabled)
1775: 			continue;
1776: 
1777: 		riscv_iommu_cmd_ats_inval(&cmd);
1778: 		riscv_iommu_cmd_ats_set_dseg(&cmd, endpoint->domid);
1779: 		riscv_iommu_cmd_ats_set_rid(&cmd, endpoint->devid);
1780: 		riscv_iommu_cmd_ats_set_pid(&cmd, domain->pscid);
1781: 		riscv_iommu_cmd_ats_set_payload(&cmd, payload);
1782: 		riscv_iommu_post(domain->iommu, &cmd);
1783: 	}
1784: 	riscv_iommu_iofence_sync(domain->iommu);
1785: }
