75: static pte_t *riscv_iommu_pt_walk_alloc(pmd_t * ptp, unsigned long iova,
76: 					unsigned shift, bool root,
77: 					size_t pgsize,
78: 					unsigned long (*pd_alloc)(gfp_t),
79: 					gfp_t gfp)
80: {
81: 	pmd_t *pte;
82: 	unsigned long pfn;
83: 
84: 	if (root)
85: 		pte = ptp + ((iova >> shift) & (PTRS_PER_PMD - 1));
86: 	else
87: 		pte = (pmd_t *) pfn_to_virt(__page_val_to_pfn(pmd_val(*ptp))) +
88: 		    ((iova >> shift) & (PTRS_PER_PMD - 1));
89: 
90: 	if ((1ULL << shift) <= pgsize) {
91: 		if (pmd_present(*pte) && !pmd_leaf(*pte))
92: 			riscv_iommu_pt_walk_free(pte, shift - 9, false);
93: 		return (pte_t *) pte;
94: 	}
95: 
96: 	if (pmd_none(*pte)) {
97: 		pfn = pd_alloc ? virt_to_pfn(pd_alloc(gfp)) : 0;
98: 		if (!pfn)
99: 			return NULL;
100: 		set_pmd(pte, __pmd((pfn << _PAGE_PFN_SHIFT) | _PAGE_TABLE));
101: 	}
102: 
103: 	return riscv_iommu_pt_walk_alloc(pte, iova, shift - 9, false,
104: 					 pgsize, pd_alloc, gfp);
105: }

107: static pte_t *riscv_iommu_pt_walk_fetch(pmd_t * ptp,
108: 					unsigned long iova, unsigned shift,
109: 					bool root, unsigned int *leaf_shift)
110: {
111: 	pmd_t *pte;
112: 
113: 	if (root)
114: 		pte = ptp + ((iova >> shift) & (PTRS_PER_PMD - 1));
115: 	else
116: 		pte = (pmd_t *) pfn_to_virt(__page_val_to_pfn(pmd_val(*ptp))) +
117: 		    ((iova >> shift) & (PTRS_PER_PMD - 1));
118: 
119: 	if (pmd_leaf(*pte)) {
120: 		if (leaf_shift)
121: 			*leaf_shift = shift;
122: 		return (pte_t *) pte;
123: 	} else if (pmd_none(*pte))
124: 		return NULL;
125: 	else if (shift == PAGE_SHIFT)
126: 		return NULL;
127: 
128: 	return riscv_iommu_pt_walk_fetch(pte, iova, shift - 9, false, leaf_shift);
129: }

131: static int riscv_iommu_map_pages(struct io_pgtable_ops *ops,
132: 				 unsigned long iova, phys_addr_t phys,
133: 				 size_t pgsize, size_t pgcount, int prot,
134: 				 gfp_t gfp, size_t *mapped)
135: {
136: 	struct riscv_iommu_domain *domain = io_pgtable_ops_to_domain(ops);
137: 	size_t size = 0;
138: 	size_t page_size = get_page_size(pgsize);
139: 	pte_t *pte;
140: 	pte_t pte_val;
141: 	pgprot_t pte_prot;
142: 
143: 	if (domain->domain.type == IOMMU_DOMAIN_BLOCKED)
144: 		return -ENODEV;
145: 
146: 	if (domain->domain.type == IOMMU_DOMAIN_IDENTITY) {
147: 		*mapped = pgsize * pgcount;
148: 		return 0;
149: 	}
150: 
151: 	pte_prot = (prot & IOMMU_WRITE) ?
152: 	    __pgprot(_PAGE_BASE | _PAGE_READ | _PAGE_WRITE | _PAGE_DIRTY) :
153: 	    __pgprot(_PAGE_BASE | _PAGE_READ);
154: 
155: 	while (pgcount--) {
156: 		pte =
157: 		    riscv_iommu_pt_walk_alloc((pmd_t *) domain->pgd_root, iova,
158: 					      PGDIR_SHIFT, true, page_size,
159: 					      get_zeroed_page, gfp);
160: 		if (!pte) {
161: 			*mapped = size;
162: 			return -ENOMEM;
163: 		}
164: 
165: 		pte_val = pfn_pte(phys_to_pfn(phys), pte_prot);
166: 
167: 		set_pte(pte, pte_val);
168: 
169: 		size += page_size;
170: 		iova += page_size;
171: 		phys += page_size;
172: 	}
173: 
174: 	*mapped = size;
175: 	return 0;

178: static size_t riscv_iommu_unmap_pages(struct io_pgtable_ops *ops,
179: 				      unsigned long iova, size_t pgsize,
180: 				      size_t pgcount,
181: 				      struct iommu_iotlb_gather *gather)
182: {
183: 	struct riscv_iommu_domain *domain = io_pgtable_ops_to_domain(ops);
184: 	size_t size = 0;
185: 	size_t page_size = get_page_size(pgsize);
186: 	pte_t *pte;
187: 
188: 	if (domain->domain.type == IOMMU_DOMAIN_IDENTITY)
189: 		return pgsize * pgcount;
190: 
191: 	while (pgcount--) {
192: 		pte = riscv_iommu_pt_walk_fetch((pmd_t *) domain->pgd_root,
193: 						iova, PGDIR_SHIFT, true, NULL);
194: 		if (!pte)
195: 			return size;
196: 
197: 		set_pte(pte, __pte(0));
198: 
199: 		iommu_iotlb_gather_add_page(&domain->domain, gather, iova,
200: 					    pgsize);
201: 
202: 		size += page_size;
203: 		iova += page_size;
204: 	}
205: 
206: 	return size;
207: }
